<original_code>
#include <bits/stdc++.h>
using namespace std;

const int LIMIT = 1000005;
const int MODULO = 1000000007;

int perm[MAX_LIMIT];
bool visited_nodes[MAX_LIMIT];
int p_num, k_num;

int main()
{
    cin >> p_num >> k_num;
    if (k_num == 0) {
        long long res = 1;
        for (int i = 1; i < p_num; ++i) {
            res = (res * p_num) % MODULO;
        }
        cout << res << "\n";
        return 0;
    }
    for (int i = 1; i < p_num; ++i) {
        perm[i] = (long long)k_num * i % p_num;
    }
    long long total_ans = 1;
    for (int start_point = 0; start_point < p_num; ++start_point) {
        if (!visited_nodes[start_point]) {
            int cycle_size = 0;
            int current_index = start_point;
            int product_modulo = 1;
            while (!visited_nodes[current_index]) {
                visited_nodes[current_index] = true;
                current_index = perm[current_index];
                cycle_size++;
                product_modulo = (long long)product_modulo * k_num % p_num;
            }
            if (cycle_size == 1) {
                int factor = (k_num == 1) ? p_num : 1;
                total_ans = (total_ans * factor) % MODULO;
            } else {
                assert(product_modulo == 1);
                total_ans = (total_ans * p_num) % MODULO;
            }
        }
    }
    cout << total_ans << "\n";
}
